CREATE TABLE IF NOT EXISTS pb4_equity (d TEXT PRIMARY KEY, equity REAL, shadow_equity REAL, open_positions INTEGER, closed_total INTEGER, closed_shadow INTEGER);
CREATE TABLE IF NOT EXISTS pb4_trades (id INTEGER PRIMARY KEY AUTOINCREMENT, d TEXT, sym TEXT, opened TEXT, closed TEXT, ret REAL, how TEXT, shadow INTEGER);
INSERT OR REPLACE INTO pb4_equity (d, equity, shadow_equity, open_positions, closed_total, closed_shadow) VALUES ('2026-10-18', 2000.0, 2000.0, 0, 0, 0);
INSERT OR REPLACE INTO books (name, registered, status, horizon, universe, direction, entry, stop, exit_rule, kill_criterion, doc, notes) VALUES ('Death-cross short v1', '2026-10-18', 'running', '4h bars, median hold ~3 days, 30-day cap', '25 registered alts (27 minus BTC, ETH)', 'short', 'anticipated 20/50 EMA death cross: EMA20>EMA50, gap<0.25 ATR14, converging 3 bars, first qualifying bar; short at the close, 4.5bp', '3 x ATR14(entry) above the lowest low since entry, worst tick', 'trail or 180-bar cap at the close; 4.5bp out', 'min 120 closed or 6 months; PASS mean>0 net AND beats the time-matched random shadow short; early kill any 25-trade block < -3%', '82', 'finding 148: +1.09%/ep t=5.3 vs +0.18% random, 85% of coins, 4/6 years better 2/6 tied. Shadow = random coin at the same bar, same exit. Kill switch: flatten=1 closes; flatten=2 (shorts only) leaves it running. src/paperbook4.py, runs/paper4_state.json');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('150', 'Golden-cross long with scaled exits (doc 82)', '2026-10-18', 'REJECTED', '4h anticipated/cross 20/50 and 9/21 longs with DK scale-out (1/3 at +1.5 ATR, stop to BE, 1/3 at +3 ATR, 3-ATR runner): -0.07% to +0.02%/ep, t<=0.3; beats random by +0.16 to +0.28pp in 59-74% of coins but never beats zero. Fixed holds 6-48 bars ~0 vs random. The entry carries information (barrier race) too small to clear costs on any exit tried. Short side with scaled exits +0.26% (t=2.7) vs trail +1.09%: the registered trail exit stands for the short.');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('151', 'Death-cross short v1 paper book registered (doc 82)', '2026-10-18', 'RUNNING', 'Pre-registered forward test of finding 148 from the information frontier (watermark 2026-10-18 08:00 UTC, no replay). 25 alts, 4h, anticipated 20/50, 3-ATR trail, 180-bar cap, 20 slots at 3x, $2,000 start; time-matched random-coin shadow short with the identical exit. Measured quantity REAL minus SHADOW. Daily in the 07:23 task as STEP 3b; tables pb4_equity/pb4_trades.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (161, 'A paper book that forward-tests an entry carries a time-matched random shadow with the identical exit from day one; the verdict is REAL minus SHADOW, never the raw P&L', 'a short book on an alt panel that drifts down collects drift; doc 80 showed k=4/5 trails doubling raw returns while the random control rose just as much', '82', '2026-10-18');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (162, 'Golden-cross longs on crypto are closed: no exit tried (trail, scaled, fixed hold) turns the entry into money; do not re-test without a new mechanism', 'finding 150: 48 cells, best +0.02%/ep', '82', '2026-10-18');
INSERT OR REPLACE INTO findings(doc,title,verdict,summary,date) VALUES ('156','AuclairsDad book on Nasdaq-100 itself (Dukascopy ticks, Jul-Oct 2026)','REJECTED','Score>=4 book -0.58 pts/trade vs random -1.10 (t=1.0, n=3002); every delta variant worse than random, barrier race 46-50% vs 50%; his management reproduces a 67-69% win rate from random entries with PF<1. Closed on both panels. Doc 86.','2026-10-19');
INSERT OR REPLACE INTO findings(doc,title,verdict,summary,date) VALUES ('157','How might AuclairsDad''s algo work? fade/divergence/absorption/night-selection/session-open passes on NQ','OPEN','Overnight NQ is a minute-scale random walk in his window (race 50% every hour); fades, divergences, ORBs, night selection and our range logic all lose to random. Only absorption (heavy 15m delta, no price progress) has the right sign in every cut (+1.1 to +1.7 pts, t~1, race 55%). Dukascopy has zero size data. Needs a true aggressor-side feed (CME trades via Databento, or Binance taker volume on crypto). Doc 87.','2026-10-19');
INSERT OR REPLACE INTO findings(doc,title,verdict,summary,date) VALUES ('158','Absorption and delta reads with TRUE aggressor delta (Binance taker volume, 18 perps, 13 months)','REJECTED','True delta has zero forward correlation at 5/15/60 min (-0.002..0). Absorption beats random by 1.5bp (a third of one side cost), never beats zero, race 50%; go-with is reliably worse than random. The AuclairsDad lead is dead on real flow; CME data not worth buying. Book 157 stays open-unresolved. Doc 88.','2026-10-19');
INSERT OR REPLACE INTO findings(doc,title,verdict,summary,date) VALUES ('159','Pump chase with trailing stop (1m/15m/1h/daily, with and without volume, 1-3 ATR trail, scale-out)','REJECTED','Continuation is real but tiny: +0.03 to +0.17pp over random on 5y 15m panel, median trade negative in every row, ~half of months positive, top 5% of trades >100% of P&L; 1m P&L 90-95% October 2025. Dump-chase short hourly +1.5% is 98% October 2025, loses -0.42%/ep over 5y at 15m. Doc 89.','2026-10-19');
INSERT OR REPLACE INTO findings(doc,title,verdict,summary,date) VALUES ('160','EMA 20/50 cross and about-to-cross entries with trailing stop, 1m/15m/1h','REJECTED','Edge over random within +-0.01pp on 1m and 15m (86k-115k and 41k-56k trades), +-0.08pp hourly; race equal to control. Entering before the cross is no better than on it. Extends finding 147. Doc 89.','2026-10-19');
INSERT OR REPLACE INTO rules(id,rule,source,date) VALUES (166,'A strategy whose top 5% of trades carry more than 100% of its P&L and whose median trade is negative is not a book for this mandate, whatever its t-statistic','doc 89','2026-10-19');
UPDATE findings SET verdict='OPEN', summary='Reopened from AuclairsDad''s own blueprint (compression->expansion, regime t-stat/R2/VR with hysteresis, setup+trigger scores, governors, stop->BE->trail). 3-month NQ build: loose stack PF 1.23, 74% win, +3.0 pts/trade, +2.9 over random (n=156); regime layer carries it. 12-month run pending. Doc 90.' WHERE doc='157';
